turns.verify:
f={D}/broken.txt; up=$(curl -s -o /dev/null -w '%{http_code}' --max-time 15 https://httpbin.org/status/200); echo "SHOW httpbin_status=$up"; test -f $f || { echo FAIL: no broken.txt; exit 0; }
python3 - "$f" "$up" <<'EOF'
import sys
got = {l.strip().strip('<>') for l in open(sys.argv[1]) if l.strip()}
want = {"https://docs.python.org/3/library/no-such-module-xyz.html", "https://httpbin.org/status/500"}
print("SHOW broken=" + ", ".join(sorted(got)))
if got == want:
    print("PASS")
elif sys.argv[2] != "200":
    print(f"FAIL: harness: httpbin.org answered {sys.argv[2]} from the box, so the working links could not be told apart")
else:
    print(f"FAIL: extra={sorted(got - want)} missing={sorted(want - got)}")
EOF
